package JavaPgm;
import java.util.*;
public class _CheckEqualityOfTwoArray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		 int[] a = {10, 20, 30};
	        int[] b = {10, 20, 30};

	        // Compare both arrays
	        boolean result = Arrays.equals(a, b);

	        System.out.println(result ? "Equal" : "Not Equal");
	}

}
